export const js="(() => {\n  if (window.__svDesign) return;\n  window.__svDesign = true;\n  const main = document.querySelector('main');\n  if (main) {\n    if (!main.id) main.id = 'sv-main';\n    main.tabIndex = -1;\n    const skip = document.createElement('a');\n    skip.href = '#' + main.id; skip.className = 'sv-skip'; skip.textContent = '본문으로 바로가기';\n    document.body.prepend(skip);\n  }\n  const path = location.pathname.replace(/\\/$/, '') || '/';\n  document.querySelectorAll('header nav a, [data-mobile-menu] a').forEach(a => {\n    const target = new URL(a.href).pathname.replace(/\\/$/, '');\n    if (path === target || path.startsWith(target + '/')) a.setAttribute('aria-current', 'page');\n  });\n  const menu = document.querySelector('[data-menu-toggle]');\n  if (menu) {\n    const syncMenu = () => menu.setAttribute('aria-label', menu.getAttribute('aria-expanded') === 'true' ? '메뉴 닫기' : '메뉴 열기');\n    new MutationObserver(syncMenu).observe(menu, {attributes:true,attributeFilter:['aria-expanded']}); syncMenu();\n  }\n  document.querySelector('header a[aria-label=\"Search\"]')?.setAttribute('aria-label', '전체 글 검색');\n  const root = document.querySelector('[data-note-modal-root]');\n  const close = root?.querySelector('button[data-note-modal-close]');\n  close?.setAttribute('aria-label', '글 닫기');\n  root?.querySelector('[role=dialog]')?.setAttribute('aria-label', '글 읽기');\n  let restoreFocus = null;\n  let inertBefore = [];\n  if (root) {\n    const sync = () => {\n      const open = root.getAttribute('aria-hidden') === 'false';\n      if (open) {\n        restoreFocus = document.activeElement;\n        inertBefore = [...root.parentElement.children].filter(e => e !== root).map(e => [e, e.inert]);\n        inertBefore.forEach(([e]) => e.inert = true);\n        close?.focus({preventScroll:true});\n      } else {\n        inertBefore.forEach(([e, inert]) => e.inert = inert); inertBefore = [];\n        if (restoreFocus instanceof HTMLElement && restoreFocus.isConnected) restoreFocus.focus({preventScroll:true});\n        restoreFocus = null;\n      }\n    };\n    new MutationObserver(sync).observe(root, {attributes:true,attributeFilter:['aria-hidden']});\n  }\n  document.addEventListener('keydown', event => {\n    if (event.key === 'Escape' && menu?.getAttribute('aria-expanded') === 'true') {menu.click();menu.focus();}\n    if (event.key !== 'Tab' || root?.getAttribute('aria-hidden') !== 'false') return;\n    const items = [...root.querySelectorAll('a[href],button,input,select,textarea,[tabindex=\"0\"]')].filter(e => !e.disabled && e.getClientRects().length);\n    const first = items[0], last = items.at(-1);\n    if (event.shiftKey && (document.activeElement === first || !root.contains(document.activeElement))) {event.preventDefault();last?.focus();}\n    else if (!event.shiftKey && (document.activeElement === last || !root.contains(document.activeElement))) {event.preventDefault();first?.focus();}\n  }, true);\n  const status = document.createElement('div'); status.className = 'sv-status';status.role = 'status';status.hidden = true;document.body.append(status);\n  let timer;\n  const notify = text => {clearTimeout(timer);status.textContent=text;status.hidden=false;timer=setTimeout(()=>status.hidden=true,2400);};\n  document.addEventListener('click', async event => {\n    const button = event.target.closest?.('[data-copy-color],[data-copy-text]');\n    if (!button) return;\n    event.preventDefault();event.stopImmediatePropagation();\n    const text = button.dataset.copyColor || button.dataset.copyText;\n    if (!text) return;\n    try {await navigator.clipboard.writeText(text);notify('클립보드에 복사했습니다.');}\n    catch {notify('복사하지 못했습니다. 텍스트를 선택해 직접 복사해주세요.');}\n  }, true);\n  const bylineHTML = '<span class=\"sv-jemissi-byline\" data-jemissi=\"byline\"><img src=\"/character/jemissi-face-v1.png\" alt=\"\" width=\"32\" height=\"32\" loading=\"lazy\" decoding=\"async\"><span>제미씨의 기록</span></span>';\n  function installBylines(scope) {\n    scope.querySelectorAll('a[data-note-modal].group, #search-results>a').forEach(card => {\n      if (!card.querySelector('[data-jemissi=\"byline\"]')) card.insertAdjacentHTML('beforeend', bylineHTML);\n    });\n    scope.querySelectorAll('[data-insight-card] > div > div').forEach(meta => {\n      if (!meta.querySelector('[data-jemissi=\"byline\"]')) meta.insertAdjacentHTML('beforeend', bylineHTML);\n    });\n    scope.querySelectorAll('main:has(>.prose-magazine)>header').forEach(header => {\n      if (!header.querySelector('[data-jemissi=\"byline\"]')) header.insertAdjacentHTML('beforeend', bylineHTML);\n    });\n  }\n  installBylines(document);\n  const noteContent = document.querySelector('[data-note-modal-content]');\n  if (noteContent) new MutationObserver(() => installBylines(noteContent)).observe(noteContent, {childList:true});\n  const results = document.querySelector('#search-results');\n  if (results) {\n    const label = document.querySelector('label:has(#search-input)>span'); if(label) label.textContent='전체 글 검색';\n    const summary=document.createElement('p');summary.className='mt-4 text-sm text-muted';summary.role='status';results.before(summary);\n    const empty = document.createElement('div'); empty.className='sv-jemissi-empty';empty.hidden=true;empty.dataset.jemissi='empty';\n    empty.innerHTML='<img src=\"/character/jemissi-thinking-v1.png\" alt=\"고개를 갸웃하며 생각하는 제미씨\" width=\"144\" height=\"144\" loading=\"lazy\" decoding=\"async\"><p>다른 단어로 찾아볼까요?</p>';\n    results.after(empty);\n    const update=()=>{installBylines(results);const count=results.querySelectorAll('a').length;empty.hidden=count>0;summary.textContent=count?`${count}개의 글을 표시합니다.`:'검색 결과가 없습니다. 다른 단어로 검색해보세요.';};\n    new MutationObserver(update).observe(results,{childList:true});update();\n  }\n  const hero = document.querySelector('[data-jemissi=\"hero\"]');\n  const blinkLayer = hero?.querySelector('.sv-jemissi-blink');\n  if (blinkLayer && 'IntersectionObserver' in window && typeof Element.prototype.animate === 'function') {\n    const reduced = matchMedia('(prefers-reduced-motion: reduce)');\n    const eyes = [...blinkLayer.querySelectorAll('.sv-jemissi-eye')];\n    let visible = false, timer = null, epoch = 0, animations = [];\n    const allowed = () => visible && !document.hidden && !reduced.matches && root?.getAttribute('aria-hidden') !== 'false';\n    const stop = () => {\n      epoch++; clearTimeout(timer); timer = null;\n      animations.forEach(animation => animation.cancel()); animations = [];\n      blinkLayer.setAttribute('hidden', ''); hero.dataset.jemissiMotion = 'paused';\n    };\n    const schedule = () => {\n      stop();\n      if (!allowed()) return;\n      hero.dataset.jemissiMotion = 'idle';\n      timer = setTimeout(blink, 12000 + Math.random() * 10000);\n    };\n    function blink() {\n      if (!allowed()) {stop();return;}\n      const current = epoch;\n      hero.dataset.jemissiMotion = 'blinking';blinkLayer.removeAttribute('hidden');\n      animations = eyes.map(eye => eye.animate([\n        {transform:'scaleY(1)',offset:0},\n        {transform:'scaleY(0.08)',offset:0.38},\n        {transform:'scaleY(0.08)',offset:0.48},\n        {transform:'scaleY(1)',offset:1}\n      ], {duration:220,easing:'ease-in-out'}));\n      Promise.all(animations.map(animation => animation.finished.catch(() => {}))).then(() => {\n        if(current === epoch) schedule();\n      });\n    }\n    new IntersectionObserver(entries => {visible=entries[0].isIntersecting && entries[0].intersectionRatio>=0.75;schedule();},{threshold:[0,0.75]}).observe(hero);\n    document.addEventListener('visibilitychange',schedule);\n    reduced.addEventListener('change',schedule);\n    // Reading, navigation and open notes take priority over decorative movement.\n    window.addEventListener('scroll',schedule,{passive:true});\n    document.addEventListener('keydown',schedule);\n    if(root) new MutationObserver(schedule).observe(root,{attributes:true,attributeFilter:['aria-hidden']});\n    window.addEventListener('pagehide',stop);\n    window.addEventListener('pageshow',schedule);\n  }\n})();\n";
export const characterAssets={"/character/jemissi-pen-v1.png":{"type":"image/png","base64":""},"/character/jemissi-face-v1.png":{"type":"image/png","base64":""},"/character/jemissi-thinking-v1.png":{"type":"image/png","base64":""},"/character/jemissi-icon-v1.png":{"type":"image/png","base64":""},"/favicon.svg":{"type":"image/svg+xml","base64":""}};
